import { describe, it } from "vitest";

describe("quote", () => {
  it.todo("empty item list -> premium 5 G (only the processing fee)");
  it.todo("plain sword, newcomer -> premium 115 G (100 base + 10 first insurance + 5 fee)");
  it.todo("plain amulet, newcomer -> premium 71 G (60 base + 6 first insurance + 5 fee)");
  it.todo("plain staff, newcomer -> premium 93 G (80 base + 8 first insurance + 5 fee)");
  it.todo("plain potion, newcomer -> premium 49 G (40 base + 4 first insurance + 5 fee)");
  it.todo("1 rune, newcomer -> premium 33 G (25 base + 2.5 first insurance + 5 fee = 32.5, rounded up)");
  it.todo("1 moonstone, newcomer -> premium 33 G (25 base, rounded up)");
  it.todo("2 runes -> 50 G base premium -> premium 60 G");
  it.todo("3 runes -> 60 G base premium (block) -> premium 71 G");
  it.todo("3 moonstones -> 60 G base premium (block) -> premium 71 G");
  it.todo("4 runes -> 100 G base premium (no block) -> premium 115 G");
  it.todo("7 runes -> 175 G base premium -> 197.5 G rounded up to premium 198 G");
  it.todo("2 runes + 1 moonstone -> 75 G base premium (different types, no block) -> premium 88 G");
  it.todo("3 runes + 3 moonstones -> 120 G base premium (two blocks) -> premium 137 G");
  it.todo("newcomer with a cursed steel sword, enchantment 3 -> premium 165 G");
  it.todo("cursed sword + plain amulet, newcomer -> curse on sword only: 160 + 50 + 16 first insurance + 5 fee = 231 G");
  it.todo("sword with enchantment 4, not cursed -> no high-enchantment surcharge -> premium 115 G");
  it.todo("sword with exactly enchantment 5, not cursed -> 30% surcharge -> premium 145 G");
  it.todo("cursed sword with exactly enchantment 5 -> both surcharges -> premium 195 G");
  it.todo("cursed sword with enchantment 4 -> only curse surcharge -> premium 165 G");
  it.todo("customer with 1 year -> no loyalty discount -> plain sword premium 115 G");
  it.todo("customer with exactly 2 years -> 20% loyalty discount -> plain sword premium 95 G");
  it.todo("second quote in the scenario, newcomer -> 15% follow-up discount -> plain sword premium 100 G");
  it.todo("long-standing customer's second contract: 3 years, cursed sword enchantment 7 -> premium 160 G");
});

describe("claim", () => {
  it.todo("schema example: 5-year customer, amulet damaged 200 G -> payout 100 G, remaining cap 1100 G");
  it.todo("regular steel sword enchantment 3, damage 500 G -> payout 400 G, remaining cap 1600 G");
  it.todo("rune damage 200 G -> payout 100 G, remaining cap 400 G");
  it.todo("steel sword enchantment 9, damage 1000 G -> 50% then deductible -> payout 400 G");
  it.todo("steel sword enchantment 7, damage 1000 G -> below 50% threshold -> payout 900 G");
  it.todo("dragon-material sword exactly enchantment 8, damage 1000 G -> payout 400 G");
  it.todo("dragon-material sword enchantment 9, damage 1000 G -> 50% rule wins -> payout 400 G");
  it.todo("dragon-material sword enchantment 5, damage 800 G -> full reimbursement -> payout 700 G, remaining cap 1300 G");
  it.todo("sword 500 G + amulet 300 G damaged in one event -> deductible per item -> payout 600 G, remaining cap 2600 G");
  it.todo("sword + amulet policy -> cap 3200 G: sword damage 200 G -> payout 100 G, remaining cap 3100 G");
  it.todo("cursed sword (premium 165 G) -> cap 2000 G from unmodified value: damage 500 G -> payout 400 G, remaining cap 1600 G");
  it.todo("sword + 3 runes -> cap 3500 G: sword damage 200 G -> payout 100 G, remaining cap 3400 G");
  it.todo("two swords -> cap 4000 G: both damaged 500 G each -> payout 800 G, remaining cap 3200 G");
  it.todo("two successive claims of 1500 G on a sword -> payouts 1400 G then 600 G, remaining cap 600 G then 0 G");
  it.todo("steel sword enchantment 9, damage 901 G -> 350.5 G rounded down to payout 350 G, remaining cap 1650 G");
  it.todo("claim references the second quote's policy by step index 1 -> amulet damage 300 G -> payout 200 G, remaining cap 1000 G");
});

describe("claim-office CLI", () => {
  it.todo("reads the schema example from stdin and writes results JSON to stdout with exit code 0");
  it.todo("quote with unknown item type broomstick -> non-zero exit, error on stderr, no results on stdout");
  it.todo("claim damaging an uninsured amulet -> non-zero exit, error on stderr, no results on stdout");
  it.todo("claim damaging an unknown item type -> non-zero exit, error on stderr, no results on stdout");
  it.todo("claim with damage amount -200 -> non-zero exit, error on stderr, no results on stdout");
  it.todo("claim with two sword damages but only one sword insured -> non-zero exit, whole claim rejected");
});

