const PROCESSING_FEE = 5;
const SWORD_BASE_PREMIUM = 100;
const FIRST_INSURANCE_SURCHARGE = 0.1;

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface ScenarioOutput {
  results: { premium: number }[];
}

export function processScenario(scenario: Scenario): ScenarioOutput {
  return {
    results: scenario.steps.map((step) => {
      const policyBasePremium = step.items.length * SWORD_BASE_PREMIUM;
      const premium = policyBasePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE;
      return { premium: Math.ceil(premium) };
    }),
  };
}

